#include "sd-event.h"

#include "alloc-util.h"
#include "resolved-dns-browse-services.h"
#include "resolved-dns-rr.h"
#include "tests.h"
#include "time-util.h"

static int dummy_handler(sd_event_source *s, uint64_t usec, void *userdata) {
        return 0;
}

TEST(mdns_service_update_huge_ttl_schedule) {
        _cleanup_(sd_event_unrefp) sd_event *e = NULL;
        _cleanup_(dns_resource_key_unrefp) DnsResourceKey *key = NULL;
        _cleanup_(dns_resource_record_unrefp) DnsResourceRecord *rr = NULL;
        DnssdDiscoveredService *service;
        usec_t t, until, armed;

        ASSERT_OK(sd_event_new(&e));

        ASSERT_NOT_NULL(key = dns_resource_key_new(DNS_CLASS_IN, DNS_TYPE_SRV, "svc._http._tcp.local"));
        ASSERT_NOT_NULL(rr = dns_resource_record_new(key));
        rr->ttl = UINT32_C(0x7fffffff);

        t = now(CLOCK_BOOTTIME);
        /* The cache caps the lifetime of a record at 2 hours from the time it was cached */
        until = usec_add(t, 2 * USEC_PER_HOUR);

        ASSERT_NOT_NULL(service = new0(DnssdDiscoveredService, 1));
        service->rr = dns_resource_record_ref(rr);
        service->until = until;
        service->rr_ttl_state = DNS_RECORD_TTL_STATE_80_PERCENT;

        ASSERT_OK(sd_event_add_time(
                          e, &service->schedule_event, CLOCK_BOOTTIME,
                          usec_add(t, USEC_PER_DAY), 0, dummy_handler, NULL));
        ASSERT_OK(sd_event_source_set_enabled(service->schedule_event, SD_EVENT_ONESHOT));

        ASSERT_OK(mdns_service_update(service, rr, t, until));

        ASSERT_OK(sd_event_source_get_time(service->schedule_event, &armed));
        log_info("now=%"PRIu64" until=%"PRIu64" armed=%"PRIu64, t, until, armed);

        /* The next maintenance query must be scheduled in the future and before the record expires */
        ASSERT_TRUE(armed >= t);
        ASSERT_TRUE(armed <= until);

        dns_service_free(service);
}

DEFINE_TEST_MAIN(LOG_DEBUG);

